export function validateManifest(m){if(!m?.files||!m?.sprites)return false;for(const s of Object.values(m.sprites)){const f=m.files[s.sheet];if(!f||!Array.isArray(s.rect)||s.rect.length!==4||!s.rect.every(Number.isFinite)||s.rect[0]<0||s.rect[1]<0||s.rect[2]<=0||s.rect[3]<=0||s.rect[0]+s.rect[2]>f.width||s.rect[1]+s.rect[3]>f.height||!Array.isArray(s.anchor)||s.anchor.length!==2)return false;}return true;}
function browserImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Could not load '+src));image.src=src;});}
export async function loadAssets(manifest,onStatus=()=>{},imageLoader=browserImage){if(!validateManifest(manifest))throw Error('Invalid sprite manifest');const images={},failed=[];await Promise.all(Object.entries(manifest.files).map(async([id,file])=>{try{images[id]=await imageLoader(file.file);}catch{images[id]=null;failed.push(id);}onStatus({id,loaded:!!images[id]});}));const sprites=Object.fromEntries(Object.entries(manifest.sprites).map(([key,s])=>[key,{...s,image:images[s.sheet]}]));return {sprites,failed};}
export function spriteFor(assetSet,key,orientation=0,frame=0){return assetSet?.sprites?.[key]??null;}
